struct Owner{libraw_data_t*p=libraw_init(0);~Owner(){if(p)libraw_close(p);}};
struct Control{std::chrono::steady_clock::time_point start=std::chrono::steady_clock::now();int ms;};
int progress(void* p,LibRaw_progress,int,int){auto*c=(Control*)p;return c->ms>0&&std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-c->start).count()>=c->ms;}
